with open(KETU_JS, 'r', encoding='utf-8') as f:
    content = f.read()

signs_match = re.search(r'signs:\s*\{', content)
if signs_match:
    insertion_point = signs_match.end()
    cancer_json = "\n    Cancer: " + json.dumps(cancer_data, indent=8) + ","
    new_content = content[:insertion_point] + cancer_json + content[insertion_point:]
    
    with open(KETU_JS, 'w', encoding='utf-8') as f:
        f.write(new_content)
    print("Added Ketu in Cancer to ketu.js")
else:
    print("Could not find signs object in ketu.js")
